/** @since 5.0 */
export type CircuitStatus = "clean" | "dirty" | "invalid" | "deleted";

export interface WaitOptions<T> {
  /**
   * The time in millisecond between remote job status requests.
   *
   * @default 1000
   */
  interval?: number;
  /**
   * Callback function that is called at the specified interval.
   * Use this method to monitor job status and messages.
   */
  statusCallback?: (result: T) => void;
}

/** @since 5.0 */
export type CircuitType = "physical" | "virtual";

/** @since 5.0 */
export type CircuitHierarchy = "consumers" | "providers" | "consumers-and-providers" | "none";

/** @since 5.0 */
export type CircuitSectionRoleType = "start-and-end" | "start" | "midspan" | "end";

/** @since 5.0 */
export type SubcircuitState = "available" | "consumed" | "reserved";

/** @since 5.0 */
export type TraceLocationType = "starting-point" | "barrier" | "stopping-point";

/** @since 5.0 */
export type TraceType = "connected" | "upstream" | "downstream" | "shortest-path" | "subnetwork" | "subnetwork-controller" | "loops" | "isolation" | "path" | "circuit";

/** @since 5.0 */
export type AssociationType = "connectivity" | "junction-junction-connectivity" | "attachment" | "containment" | "junction-edge-from-connectivity" | "junction-edge-midspan-connectivity" | "junction-edge-to-connectivity";

/** @since 5.0 */
export type AssociationJsonType = "connectivity" | "junctionJunctionConnectivity" | "attachment" | "containment" | "junctionEdgeFromConnectivity" | "junctionEdgeMidspanConnectivity" | "junctionEdgeToConnectivity";

/** @since 5.0 */
export type AssociationListPopupType = "attachment" | "connectivity" | "container" | "content" | "structure";

/** @since 5.0 */
export type ValidationType = "normal" | "rebuild" | "force-rebuild";